//! Known-answer vectors for the crypto HIL tests, generated with Python `cryptography`
//! (see `gen_crypto_vectors.py`).
#![allow(dead_code)]

/// Deterministic test data.
pub fn pattern(buf: &mut [u8], seed: u8) {
    for (i, b) in buf.iter_mut().enumerate() {
        *b = (seed as u32 * 31 + i as u32 * 7 + (i as u32 >> 3)) as u8;
    }
}

pub struct CcmVector {
    pub nonce_len: usize,
    pub tag_len: usize,
    pub aad_len: usize,
    pub pt_len: usize,
    pub ct: &'static [u8],
    pub tag: &'static [u8],
}
pub struct AeadVector {
    pub aad_len: usize,
    pub pt_len: usize,
    pub ct: &'static [u8],
    pub tag: [u8; 16],
}

